395	    /// The component published under `key`, with its own diagnostics. A lazy session resolves it now, or answers from
396	    /// what an earlier request resolved; the answer is the one a batch extraction of the same files publishes under
397	    /// that key. `None` for a key with no component, and before `initialize`.
398	    pub fn component(&self, key: &str) -> Option<ComponentAnswer> {
399	        let revision = self.current.load_full()?;
400	        let answer = match revision.is_lazy() {
401	            true => {
402	                let answer = revision.lazy_component(&self.options, key);
403	                revision.load_whole_demand_in_background(&self.options);
404	                answer
405	            }
406	            false => revision.published_component(key),
407	        };
408	        self.refined(answer, Priority::Interactive)
409	    }
