/// The component published under `key`, with its own diagnostics. A lazy session resolves it now, or answers from
/// what an earlier request resolved; the answer is the one a batch extraction of the same files publishes under
/// that key. `None` for a key with no component, and before `initialize`.
pub fn component(&self, key: &str) -> Option<ComponentAnswer> {
    let revision = self.current.load_full()?;
    let answer = match revision.is_lazy() {
        true => {
            let answer = revision.lazy_component(&self.options, key);
            revision.load_whole_demand_in_background(&self.options);
            answer
        }
        false => revision.published_component(key),
    };
    self.refined(answer, Priority::Interactive)
}

/// `answer` with the attached checker's props, when there is a checker and it answers within the wait `priority`
/// gives it.
fn refined(&self, answer: Option<ComponentAnswer>, priority: Priority) -> Option<ComponentAnswer> {
    match (&self.semantic, answer) {
        (Some(hook), Some(answer)) => Some(hook.refine(
            answer,
            self.options.html_attributes,
            crate::types::options::CollapseContext::of(&self.options),
            priority,
        )),
        (_, answer) => answer,
    }
}

/// Wait for the dependency declarations a lazy session loads in the background after its first answer (the names
/// every project file takes from a package, so later requests grow the dependency layer no further). A request
/// never needs this; a benchmark or a test that wants a settled session does. Returns at once for an eager
/// session, one without `load_dependencies`, and before the first answer.
pub fn wait_for_dependency_load(&self) {
    if let Some(revision) = self.current.load_full() {
        revision.wait_for_dependency_load();
    }
}

/// The component `name` declared in `file`, found without knowing its key (which depends on what else the project
/// names the same). `file` may be relative or reach the project through a symlink. `None` when the file declares
/// no such component, and before `initialize`.
pub fn component_in(&self, file: &Utf8Path, name: &str) -> Option<ComponentAnswer> {
    let file = canonicalize_best_effort(file);
    let revision = self.current.load_full()?;
    let key = match revision.is_lazy() {
        true => revision.lazy_key_in(&self.options, &file, name)?,
        false => revision
            .output
            .components
            .iter()
            .find(|(_, entry)| entry.display_name == name && entry.file_path == file)
            .map(|(key, _)| key.clone())?,
    };
    self.component(&key)
}

/// The component published under `key` as react-docgen-typescript documents it (`__docgenInfo`, the shape
/// Storybook converts to argTypes), resolving it first in a lazy session.
pub fn docgen_info(&self, key: &str) -> Option<serde_json::Value> {
    Some(super::rdt::docgen_info(&self.component(key)?.entry))
}

/// [`Self::component`] for each of `keys`, resolved in parallel.
pub fn components(&self, keys: &[String]) -> Vec<Option<ComponentAnswer>> {
    self.components_at(keys, Priority::Interactive)
}

/// [`Self::components`] for work nobody waits for yet: a warm-up, a fill, a prefetch of the components stories
/// name. With a checker attached, each is asked for at [`Priority::Background`] and not waited for, so the call
/// returns the structural answers; the checker answers them after every request someone waits for, and keeps its
/// answers for the requests that follow. A request for a component already being asked joins that request.
pub fn components_in_background(&self, keys: &[String]) -> Vec<Option<ComponentAnswer>> {
    self.components_at(keys, Priority::Background)
}

fn components_at(&self, keys: &[String], priority: Priority) -> Vec<Option<ComponentAnswer>> {
    use rayon::prelude::*;
    let Some(revision) = self.current.load_full() else { return vec![None; keys.len()] };
    match revision.is_lazy() {
        true => {
            let answers = revision.lazy_components(&self.options, keys);
            revision.load_whole_demand_in_background(&self.options);
            answers.into_iter().map(|answer| self.refined(answer, priority)).collect()
        }
        false => keys.par_iter().map(|key| self.refined(revision.published_component(key), priority)).collect(),
    }
}

/// Every key [`Self::component`] answers, sorted. A lazy session resolves only the imported-member aliases to
/// decide; the rest come from parsing alone.
pub fn component_keys(&self) -> Vec<String> {
    let Some(revision) = self.current.load_full() else { return Vec::new() };
    match revision.is_lazy() {
        true => revision.lazy_keys(&self.options),
        false => revision.output.components.keys().cloned().collect(),
    }
}

/// Where each component [`Self::component_keys`] lists is declared, sorted by key. A lazy session answers from
/// parsing alone; nothing is resolved.
pub fn component_index(&self) -> Vec<ComponentLocation> {
    let Some(revision) = self.current.load_full() else { return Vec::new() };
    match revision.is_lazy() {
        true => revision.lazy_index(&self.options),
        false => revision
            .output
            .components
            .iter()

