732	    /// queued ([`OnDemand::hold`]); it then files every queued job before it picks one, so the order does not depend on
733	    /// how fast the test thread queues them. The answers arrive in the order the one worker gives them.
734	    #[test]
735	    fn a_story_asked_behind_queued_background_requests_is_answered_before_them() {
736	        let dir = tempfile::Builder::new().prefix("OnDemand").tempdir().unwrap();
737	        let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
738	        let fixtures = Utf8PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/project");
