45:struct Read {
46:    /// What is kept for the next request: the component and what the checker said about the request, each diagnostic
47:    /// naming the component.
48:    answered: Answered,
49:    /// What an unavailable checker says, which a session says once and not per component, so it is not kept.
50:    once: Vec<Diagnostic>,
51:}
52:
53:/// The answer for the component whose output key is `asked`, and the diagnostics the request produced: a warning that
54:/// came with an answer (an edit the checker was not told about) is about this request, and its fallback's reason says
55:/// why the component kept its structural result. An answer or fallback for another key is not this component's.
56:fn read_outcome(asked: &str, outcome: SemanticOutcome) -> Read {
57:    let SemanticOutcome { components, fallbacks, diagnostics: reported } = outcome;
58:    // Only an outcome with no answer at all says the checker is unavailable.
59:    let unavailable = components.is_empty() && fallbacks.is_empty();
60:    let mut read = Read { answered: Answered::default(), once: Vec::new() };
61:    for mut diagnostic in reported {
62:        diagnostic.affects = vec![asked.to_owned()];
63:        if unavailable && diagnostic.severity == DiagnosticSeverity::Warning {
64:            read.once.push(diagnostic);
65:        } else {
66:            read.answered.diagnostics.push(diagnostic);
67:        }
68:    }
69:    for SemanticFallback { key, reason } in fallbacks {
70:        if key != asked {
71:            continue;
72:        }
73:        let mut info = Diagnostic::new(
74:            DiagnosticSeverity::Info,
75:            DiagnosticCode::SemanticBackend,
76:            format!("1 component(s) kept their structural result: {reason}"),
77:        );
78:        info.affects = vec![key];
79:        read.answered.diagnostics.push(info);
80:    }
81:    read.answered.component = components.into_iter().find(|found| found.key == asked).map(Arc::new);
82:    read
83:}
