/// The requests waiting for the checker, in the order they arrived. The next is the oldest of the class answered
/// first ([`Priority`]: interactive, then neighbour, then background), read again at each pick since a caller may
/// raise a request while it waits. A request cancelled while it waited ([`SharedPriority::cancel`]) is dropped when the
/// next is picked, before it is converted, which hands its delivery `None`; one the checker already took is not
/// interrupted. After [`INTERACTIVE_STREAK`] requests of the first class in a row while a lesser class waits, the next is
/// the oldest request of a lesser class.
struct Queue<T> {
    waiting: VecDeque<(T, SharedPriority)>,
    /// Requests of the first class taken in a row while one of a lesser class waited.
    streak: u32,
}

impl<T> Default for Queue<T> {
    fn default() -> Self {
        Self { waiting: VecDeque::new(), streak: 0 }
    }
}

impl<T> Queue<T> {
    fn push(&mut self, item: T, priority: SharedPriority) {
        self.waiting.push_back((item, priority));
    }

    fn is_empty(&self) -> bool {
        self.waiting.is_empty()
    }

    /// The request the checker answers next.
    fn next(&mut self) -> Option<T> {
        self.waiting.retain(|(_, priority)| !priority.is_cancelled());
        // Read once, so a request raised during the pick does not change the class it was picked by.
        let classes: Vec<Priority> = self.waiting.iter().map(|(_, priority)| priority.get()).collect();
        let first = classes.iter().min().copied()?;
        let lesser_waits = classes.iter().any(|class| *class > first);
        let starving = lesser_waits && self.streak >= INTERACTIVE_STREAK;
        let index = match starving {
            true => classes.iter().position(|class| *class > first),
            false => classes.iter().position(|class| *class == first),
        }?;
        self.streak = match (starving, lesser_waits) {
            (false, true) => self.streak + 1,
            _ => 0,
        };
        self.waiting.remove(index).map(|(item, _)| item)
    }
}

